/**
 * The tallies this run shows.
 *
 * A tally kept per racer belongs on the scoreboard, next to the name it
 * belongs to, and a hidden one is the pack keeping something from the
 * player. Both rules are here rather than in the panel below, because a
 * deck is offered the same list the panel draws and the two must not be
 * able to disagree about it.
 */
function shownCounters(pack: Pack, state: RunState) {
