  it("offers ticking the whole list and pressing Done on a manual checklist", () => {
    const offer = offerOf({
      ...base,
      step: { kind: "manual", checklist: [{ text: "Matches the roll" }, { text: "Signed it" }] } as never,
      stepLabel: "Sketch the room",
