  it("refuses to end a run that is not at its ending", () => {
    const act = acts();
    expect(press({ finish: true }, offer, act)).toEqual({ ok: false, say: "The run cannot end here." });
    expect(act.finish).not.toHaveBeenCalled();
  });
});

